"""Explain metadata continuity limits and origin record formats."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1737': ('원본 공책의 두 쪽이 이어져 있어도 따로 보관한 검사표 두 쪽까지 이어져 있다고 단정할 수는 없어요. 검사표의 위치도 각각 확인해야 해요.', '데이터와 두 검사 정보의 주소 간격을 구별합니다.', '페이지4096일 때 shadow10000→14096,origin30000→34096을 적고 두 차이가4096인지 계산하세요.', ['kmsan_metadata_is_contiguous는 검사 정보가 기대한 방식으로 이어지는지 확인하는 helper예요. contiguous는 사이가 끊기지 않고 이어진다는 뜻이에요. shadow는 준비 상태, origin은 원인 기록을 담는 검사 정보예요.', '길이가0이면 바로 true를 반환해요. 길이가 있는 범위도 시작과 마지막 바이트가 같은 데이터 페이지에 있으면 true예요. 이 경우 여러 페이지 사이의 간격을 비교하는 반복문으로 가지 않아요. true가 모든 데이터의 초기화 상태를 검사했다는 뜻은 아니에요.', '여러 페이지를 비교하는 경로에서는 현재 shadow 주소가 다음 shadow 주소-PAGE_SIZE인지 확인해요. origin 주소도 같은 방식으로 확인해요. 두 검사 정보의 간격이 모두 맞아야 해당 비교를 통과해요.', '페이지4096인 숫자 예에서 shadow10000과14096의 차이는4096이에요. origin30000과34096도4096이에요. 다음 origin만38192라면 간격8192가 되므로 같은 조건을 만족하지 않아요. 이 숫자는 간격 계산용 예시예요.', 'origin 기록 하나의 단위가4바이트라는 것과 이 주소 비교의 간격은 달라요. 여기서는 한 페이지만큼 떨어진 데이터 위치에 대응하는 메타데이터 주소 차이를 보므로 PAGE_SIZE를 써요. 원인 단위4를 페이지 간격에 대신 넣으면 틀려요.', '이 설명은 실제로 비교하는 반복문 안의 조건이에요. 어떤 주소들이 반복문에 들어오는지는 시작과 길이 계산에 달려 있어요. 다음 수업에서 짧게 페이지를 넘는 경우도 따로 살펴보며, 함수 이름만으로 모든 경계를 빠짐없이 확인한다고 가정하지 않아요.'], [('이 코드가 페이지 사이 origin 주소에서 확인하는 간격은 얼마인가요?', ['항상4바이트예요', 'PAGE_SIZE예요'], '정답은 두 번째예요. 원문은 next_origin-PAGE_SIZE와 cur_origin을 비교해요. 원인 한 단위4바이트와 페이지별 메타데이터 간격을 구별하세요.'), ('길이가0이면 이 연속성 helper는 무엇을 반환하나요?', ['true예요', '언제나false예요'], '정답은 첫 번째예요. 맨 앞에 if(!size) return true가 있어요. 검사할 범위가 없다는 처리이며 실제 데이터가 모두 준비됐다는 판정은 아니에요.')]), 'os1738': ('모든 쪽에 검사표가 없는 경우와 어떤 쪽에만 검사표가 있는 경우는 달라요. 이 함수는 전부 없는 경우를 별도 상태로 기억해요.', '모두 미추적인 범위와 추적 상태가 섞인 범위를 구별합니다.', '정렬된 두 페이지에 각각 shadow·origin없음/없음을 적은 예와 없음/있음 예를 나눠 그리세요.', ['미추적은 해당 범위의 검사 정보가 없는 상태예요. 이 연속성 함수는 여러 페이지를 다룰 때 첫 shadow를 찾아요. 없으면 all_untracked를 참으로 놓아 모두 미추적이어야 하는 경로임을 기억해요.', '첫 shadow는 없는데 origin만 있으면 report라는 진단 위치로 가요. shadow와 origin은 서로 연결된 검사 정보이므로 이런 모양을 정상적인 전부 미추적 상태로 취급하지 않아요.', '반복문에서 다음 페이지 위치를 볼 때 all_untracked이면 다음 shadow나 origin 중 하나라도 있는지 확인해요. 하나라도 있으면 진단으로 가요. 둘 다 없으면 다음 위치로 계속 진행해요. 따라서 비교 대상이 모두 미추적이면 true로 끝날 수 있어요.', '정렬된 두 페이지를 예로 들면 첫 페이지도 두 정보가 없고 둘째도 없을 때는 이 경로를 통과해요. 첫 페이지는 없는데 둘째에 검사 정보가 있으면 혼합 상태라 진단 후false예요. 여기서는 실제로 두 번째 위치까지 반복하는 크기의 요청을 가정해요.', '추적되는 경로에서는 shadow와 origin의 페이지 간격을 각각 비교해요. 진단 경로에서는 주소·간격 정보를 로그로 남기고, 원인 정보가 있으면 그 원인도 출력해요. 없으면 원인을 사용할 수 없다고 표시하므로 원인 기록이 언제나 출력되는 것은 아니에요.', '전부 미추적인데 true라는 것은 모든 바이트가 안전하다는 뜻이 아니에요. 이 함수의 검사 정보 배치 조건을 만족했다는 뜻이에요. 검사 정보가 존재하는지와 실제 값이 초기화됐는지는 서로 다른 질문이에요.'], [('정렬된 여러 페이지에 shadow와 origin이 모두 없으면 true가 될 수 있나요?', ['아니요. 정보가 항상 있어야만true예요', '네. 전부 미추적인 경우로 처리할 수 있어요'], '정답은 두 번째예요. all_untracked 경로는 뒤의 비교 위치도 두 정보가 모두 없는지 살펴요. 이는 데이터 초기화 확인이 아니라 메타데이터 배치 처리예요.'), ('첫 페이지는 미추적이고 다음 비교 페이지에만 정보가 있으면 전부 미추적인 정상 경우인가요?', ['아니요. 진단 경로로 가서false를 반환해요', '네. 추적 정보가 어떻게 섞여도 허용해요'], '정답은 첫 번째예요. all_untracked인데 next_shadow 또는 next_origin이 있으면 report로 이동해요. 전부 없음과 일부 있음은 다른 경우예요.')]), 'os1739': ('다음 쪽 시작으로 가는 것과 지금 위치에서 한 쪽 길이만큼 걷는 것은 달라요. 쪽 끝 가까이에서 시작하면 두 도착점의 차이가 크게 보여요.', '반복 주소의 증가식과 실제 페이지 경계를 숫자로 비교합니다.', '페이지4096,시작4092,길이8로 놓고 다음경계4096·요청끝4100·next_addr8188을 적으세요.', ['이 고정 원본의 next_addr는 cur_addr+PAGE_SIZE예요. 다음 페이지의 시작으로 정렬하는 식이 아니에요. 현재 위치가 페이지 안에서 어디든 그대로 한 페이지 크기를 더하므로 그 위치의 나머지도 유지돼요.', '페이지 크기4096이고 시작이4092라면 현재 페이지 끝까지4바이트예요. 길이8의 마지막 포함 주소는4099이고 요청 끝의 제외 주소는4100이에요. 실제 범위는 다음 페이지4096을 넘어가므로 같은 페이지라는 빠른 반환 조건은 맞지 않아요.', '그런데 next_addr는4092+4096=8188이에요. 반복 조건은 next_addr<addr+size이므로8188<4100을 비교해요. 거짓이어서 반복문은 한 번도 실행되지 않아요. 다음 경계4096과 next_addr8188을 같은 숫자라고 읽으면 안 돼요.', '초기 메타데이터 검사에서 진단으로 가지 않는 상황이라면 반복문을 건너뛰고 true를 반환해요. 예를 들어 시작점의 shadow와 origin이 정상적으로 둘 다 있는 경우를 생각할 수 있어요. shadow없이 origin만 있는 초기 오류까지 무조건true라고 일반화하면 안 돼요.', '따라서 이 입력에서 true였다는 사실만으로 다음 페이지의 모든 메타데이터 배치를 비교했다고 말할 수 없어요. 함수가 하는 일을 이름으로 추측하기보다 초기값·증가식·종료 조건을 실제 숫자로 대입해야 해요.', '이것은 고정 소스의 반복 범위를 읽은 결과예요. 실제 커널에서 어떤 매핑 전제를 지키는지, 후속 접근이 어떻게 이루어지는지는 함께 살펴야 해요. 이 계산 하나를 모든 임의 매핑의 안전성 보장이나 실제 장애 재현으로 바꾸어 말하지 않아요.'], [('시작PAGE_SIZE-4·길이8에서 next_addr 반복문은 실행되나요?', ['네. 무조건 다음 페이지 시작으로 가요', '아니요. 시작+PAGE_SIZE가 요청 끝보다 커서 실행되지 않아요'], '정답은 두 번째예요. 페이지4096이면 next_addr8188,요청끝4100이에요. 다음 경계4096으로 정렬하는 코드가 아니라는 점이 핵심이에요.'), ('이 경우true가 나왔다고 모든 불연속 매핑을 검사했다고 해도 되나요?', ['아니요. 실제 반복 위치와 매핑 전제를 확인해야 해요', '네. 모든 페이지 경계를 빠짐없이 비교했다는 뜻이에요'], '정답은 첫 번째예요. 이 짧은 경계 예에서는 반복문을 건너뛰어요. 반환값의 의미를 실제 수행한 비교보다 넓혀 해석하면 안 돼요.')]), 'os1740': ('기록 카드의 종류를 알아보려면 표지와 칸 수를 함께 확인해요. 세 칸짜리 카드를 네 칸짜리 양식처럼 읽으면 마지막 칸을 잘못 해석할 수 있어요.', '원인 기록을 항목 개수와 표식으로 나눠 해석하는 원리를 이해합니다.', 'alloca카드4칸:표식·설명·코드위치1·코드위치2와 chain카드3칸:표식·현재스택·이전원인을 그리세요.', ['kmsan_print_origin은 저장된 원인 기록을 꺼내 설명하는 함수예요. origin은 그 기록의 식별자이고 stack_depot_fetch가 항목 배열과 개수를 알려 줘요. 먼저 origin이0이면 바로 돌아가요.', 'magic은 기록 종류를 알려 주는 특별한 표식이에요. 항목이 있으면 첫 칸을 magic으로 읽고 없으면0으로 놓아요. 표식만 보는 것이 아니라 nr_entries라는 항목 개수도 함께 비교해요.', '항목4개와 ALLOCA_MAGIC_ORIGIN이 모두 맞으면 지역 변수 생성 관련 형식으로 해석해요. 첫 칸은 표식,둘째는 변수 설명,셋째와 넷째는 코드 위치pc1·pc2예요. PC는 여기서 실행 코드 위치와 관련되며 개인용 컴퓨터라는 뜻으로 읽지 않아요.', '항목3개와 CHAIN_MAGIC_ORIGIN이 모두 맞으면 복사 등으로 이어진 원인 연결 형식이에요. 첫 칸은 표식,둘째는 현재 호출 기록의 식별자,셋째는 이전 원인 식별자예요. 앞서 core.c에서 만든 세 칸의 저장 형식과 읽는 쪽을 연결해 보세요.', '왜 개수도 확인할까요? 각 형식이 어느 칸을 어떤 정보로 읽는지 다르기 때문이에요. magic만 같다고 길이가 다른 배열을 같은 형식으로 다루면 정해진 기록 계약과 맞지 않아요. 실제 데이터 버퍼 전체를 이 배열에 저장하는 구조도 아니에요.', 'chain 경로는 이번 호출 기록을 설명하고 이전 원인으로 이어가요. 깊이 상한에 도달한 기록이면 메모리 절약을 위해 일부 호출 기록을 남기지 않았을 수 있다는 안내도 있어요. 출력되는 원인 연결을 모든 과거 호출의 완전한 목록이라고 가정하지 마세요.'], [('alloca와 chain을 구별할 때 magic만 확인하나요?', ['네. 모든 배열을 같은 형식으로 읽어요', '아니요. 각각4개·3개라는 항목 수도 확인해요'], '정답은 두 번째예요. 원문 조건에는 항목 개수와 magic 비교가 함께 있어요. 형식마다 필요한 칸과 의미가 다르므로 둘 다 확인해요.'), ('chain 기록은 무엇을 연결하나요?', ['현재 복사 관련 호출 기록과 이전 원인이에요', '항상 실제 사용자 데이터 버퍼 전체예요'], '정답은 첫 번째예요. 세 칸은 표식·현재 스택 식별자·이전 원인 식별자예요. 문제의 경로를 설명하는 검사 기록이며 실제 데이터 내용과는 달라요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_430.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
